contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(amount > 0);
        require(amount <= type(uint128).max);

        // Drive one openTake. The call will either revert (preserving the invariant
        // trivially) or succeed, in which case the postcondition must hold.
        c.openTake(UFixed18.wrap(amount));

        // The max-utilization invariant must hold on the new next position:
        // utilization = taker / maker must be <= 1.
        Position memory next = c.positionAtVersion(c.latestVersion());
        UFixed18 utilization = next.taker.unsafeDiv(next.maker);
        assert(utilization.lte(UFixed18Lib.ONE));
    }

    receive() external payable {}
}

