contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address account, uint256 amount) public payable {
        require(account != address(0), "zero account");
        require(amount > 0, "zero amount");

        try c.openMakeFor(account, UFixed18.wrap(amount)) {
            // opened successfully; check the recorded positions
            Position memory accountPosition = c.position(account);
            PrePosition memory accountPre = c.pre(account);

            assert(accountPosition.maker >= UFixed18.wrap(amount));
            assert(accountPre.openPosition.maker >= UFixed18.wrap(amount));
        } catch {
            // If the product was not initialized / closed / otherwise rejecting,
            // the account must not have any maker position recorded.
            Position memory accountPosition = c.position(account);
            assert(accountPosition.maker == UFixed18.wrap(0));
        }
    }

    receive() external payable {}
}

