contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address account, uint256 amount) public payable {
        require(account != address(0), "zero account");
        require(amount > 0, "zero amount");

        Position memory beforePosition = c.position(account);
        PrePosition memory beforePre = c.pre(account);
        uint256 beforeMaker = UFixed18.unwrap(beforePosition.maker);
        uint256 beforePreOpenMaker = UFixed18.unwrap(beforePre.openPosition.maker);

        bool reverted;
        try c.openMakeFor(account, UFixed18.wrap(amount)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        Position memory afterPosition = c.position(account);
        PrePosition memory afterPre = c.pre(account);
        uint256 afterMaker = UFixed18.unwrap(afterPosition.maker);
        uint256 afterPreOpenMaker = UFixed18.unwrap(afterPre.openPosition.maker);

        if (reverted) {
            assert(afterMaker == beforeMaker && afterPreOpenMaker == beforePreOpenMaker);
        } else {
            assert(afterPreOpenMaker == addNoOverflow(beforePreOpenMaker, amount) && afterMaker == addNoOverflow(beforeMaker, amount));
        }
    }

    function addNoOverflow(uint256 a, uint256 b) private pure returns (uint256) {
        uint256 r = a + b;
        require(r >= a, "overflow");
        return r;
    }

    receive() external payable {}
}

