contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 newFundingFeeRaw) public {
        UFixed18 newFundingFee = UFixed18.wrap(newFundingFeeRaw);

        bool overOne = newFundingFee.gt(UFixed18Lib.ONE);
        UFixed18 before = c.fundingFee();

        bool reverted;
        try c.updateFundingFee(newFundingFee) {
            reverted = false;
        } catch {
            reverted = true;
        }

        UFixed18 after = c.fundingFee();

        // General rule: updateFundingFee reverts exactly when the proposed fee exceeds ONE,
        // and only in the non-reverting case can the stored fundingFee change (to the proposed value).
        if (overOne) {
            assert(reverted);
        } else {
            assert(!reverted);
            assert(after.eq(newFundingFee));
        }
    }
}

